def bond_price(face, coupon_rate, ytm, years, freq=2):
    periods = int(years * freq)
    coupon = face * coupon_rate / freq
    r = ytm / freq
    return sum((coupon + (face if t == periods else 0)) / (1 + r) ** t
               for t in range(1, periods + 1))

def solve_ytm(price, face, coupon_rate, years, freq=2):
    low, high = 0.0, 0.50
    for _ in range(100):
        mid = (low + high) / 2
        if bond_price(face, coupon_rate, mid, years, freq) > price:
            low = mid   # trial price too high, so the yield must be higher
        else:
            high = mid  # trial price too low, so the yield must be lower
    return mid

print(f"YTM: {solve_ytm(103.20, 100, 0.084, 6):.4%}")  # YTM: 7.7235%
